 FOR p IN SELECT value FROM jsonb_array_elements('[{"max_views":0},{"duration_hours":-1},{"duration_hours":9000},{"included_sections":["unknown"]},{"can_edit":true},{"can_upload":true},{"permissions":{"ownership.manage":true}}]'::jsonb) LOOP
