  PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('3',64),recipient,NULL,repeat('f',64)),'SHARE_RESOURCE_DENIED');
 UPDATE public."HomeOccupancy" SET verification_status='verified',role=NULL,role_base=NULL
  WHERE home_id=h AND user_id=recipient;
 PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('3',64),recipient,NULL,repeat('f',64)),'SHARE_RESOURCE_DENIED');
 DELETE FROM public."HomeOccupancy" WHERE home_id=h AND user_id=recipient;
 UPDATE public."HomeScopedGrant" SET start_at=clock_timestamp()+interval '1 hour' WHERE id=sid;
 PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('3',64),recipient,NULL,repeat('f',64)),'SHARE_NOT_STARTED');
 UPDATE public."HomeScopedGrant" SET start_at=clock_timestamp()-interval '1 hour',can_view=false WHERE id=sid;
 PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('3',64),recipient,NULL,repeat('f',64)),'SHARE_DENIED');
 UPDATE public."HomeScopedGrant" SET can_view=true WHERE id=sid;
 -- One page view admits an exact short-lived document receipt. Download
 -- authorization must remain usable when that one view exhausted the quota.
 p:=jsonb_build_object('resource_type','HomeDocument','resource_id',doc,'token_hash',repeat('4',64),
   'max_views',1,'passcode_hash',repeat('a',64));
 r:=public.mutate_home_external_share(h,o,'scoped','create',NULL,p);
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Document grant failed'; END IF;
 sid:=(r->'record'->>'id')::uuid; INSERT INTO share_fixture_ids VALUES('document',sid);
 PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('4',64),NULL,NULL,repeat('5',64)),'SHARE_PASSCODE_REQUIRED');
 r:=public.read_home_external_share('scoped',repeat('4',64),NULL,repeat('a',64),repeat('5',64));
 IF r->'view'->'resource'->>'id' IS DISTINCT FROM doc::text OR NOT r->'view'->'resource' ? '_document'
  OR r->'view'->'resource' ?| ARRAY['storage_path','storage_bucket','details'] THEN RAISE EXCEPTION 'Document receipt metadata failed'; END IF;
 r:=public.authorize_home_share_document(repeat('5',64),doc);
 IF r->>'ok' IS DISTINCT FROM 'true' OR r->'document'->'_document'->>'sha256' IS DISTINCT FROM repeat('b',64) THEN RAISE EXCEPTION 'One-view receipt unavailable'; END IF;
 PERFORM pg_temp.expect_share(public.read_home_external_share('scoped',repeat('4',64),NULL,repeat('a',64),repeat('6',64)),'SHARE_VIEW_LIMIT');
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('5',64),'ddf00000-0000-4000-8000-000000000699'),'SHARE_DENIED');
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('5',64),doc,recipient),'SHARE_DENIED');
 UPDATE public."HomeShareReadReceipt" SET expires_at=clock_timestamp()-interval '1 second' WHERE receipt_hash=repeat('5',64);
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('5',64),doc),'SHARE_DENIED');
 UPDATE public."HomeShareReadReceipt" SET expires_at=clock_timestamp()+interval '1 minute' WHERE receipt_hash=repeat('5',64);
 UPDATE public."HomeDocument" SET visibility='sensitive' WHERE id=doc;
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('5',64),doc),'SHARE_RESOURCE_DENIED');
 UPDATE public."HomeDocument" SET visibility='members' WHERE id=doc;
 PERFORM public.mutate_home_external_share(h,o,'scoped','revoke',sid);
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('5',64),doc),'SHARE_REVOKED');
 -- A receipt spends no extra page view, but each exact document can be
 -- delivered once only, at the final authorization after the byte fetch.
 r:=public.mutate_home_external_share(h,o,'scoped','create',NULL,p||jsonb_build_object('token_hash',repeat('8',64)));
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Single-use receipt fixture failed'; END IF;
 sid:=(r->'record'->>'id')::uuid;
 r:=public.read_home_external_share('scoped',repeat('8',64),NULL,repeat('a',64),repeat('8',64));
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Single-use receipt view failed'; END IF;
 r:=public.authorize_home_share_document(repeat('8',64),doc,NULL,true);
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'First final receipt authorization failed'; END IF;
 PERFORM pg_temp.expect_share(public.authorize_home_share_document(repeat('8',64),doc,NULL,true),'SHARE_DENIED');
 IF (SELECT view_count FROM public."HomeScopedGrant" WHERE id=sid)<>1 THEN RAISE EXCEPTION 'Download spent an extra view'; END IF;
END $$;
