-- An orphaned retained receipt must never turn an established setup into a
-- deletable private bootstrap after its original share has been removed.
DO $$ DECLARE h uuid:='ddf00000-0000-4000-8000-000000000300';
 u uuid:='ddf00000-0000-4000-8000-000000000006'; r jsonb;
BEGIN
 r:=public.home_delete_eligibility(h,u);
 IF r->>'allowed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Private receipt fixture not eligible initially'; END IF;
 INSERT INTO public."HomeShareReadReceipt"(receipt_hash,home_id,share_kind,share_id,document_ids,expires_at)
  VALUES(repeat('c',64),h,'guest','ddf00000-0000-4000-8000-000000000999','{}',clock_timestamp()+interval '1 minute');
 r:=public.home_delete_eligibility(h,u);
 IF r->>'code' IS DISTINCT FROM 'HOME_DELETE_ESTABLISHED_HOUSEHOLD' OR r->>'allowed' IS DISTINCT FROM 'false' THEN
  RAISE EXCEPTION 'Private deletion ignored retained sharing history'; END IF;
 DELETE FROM public."HomeShareReadReceipt" WHERE receipt_hash=repeat('c',64);
END $$;

-- Downstream audit/view/receipt failures roll back the complete operation.
CREATE FUNCTION pg_temp.fail_external_share() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 RAISE EXCEPTION 'Synthetic sharing downstream failure' USING ERRCODE='P0994'; END $$;
CREATE TRIGGER sharing_audit_failure BEFORE INSERT ON public."HomeAuditLog"
 FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_external_share();
DO $$ DECLARE before_passes bigint; before_grants bigint; h uuid:='ddf00000-0000-4000-8000-000000000100';
 o uuid:='ddf00000-0000-4000-8000-000000000001'; kind text; p jsonb;
BEGIN
 SELECT count(*) INTO before_passes FROM public."HomeGuestPass" WHERE home_id=h;
 SELECT count(*) INTO before_grants FROM public."HomeScopedGrant" WHERE home_id=h;
 FOREACH kind IN ARRAY ARRAY['guest','scoped'] LOOP
  p:=CASE kind WHEN 'guest' THEN jsonb_build_object('label','Rollback','included_sections',jsonb_build_array('parking'),'token_hash',repeat('9',64))
    ELSE jsonb_build_object('resource_type','HomeTask','resource_id','ddf00000-0000-4000-8000-000000000501','token_hash',repeat('9',64)) END;
  BEGIN
   PERFORM public.mutate_home_external_share(h,o,kind,'create',NULL,p);
   RAISE EXCEPTION 'Missing sharing audit failure';
  EXCEPTION WHEN SQLSTATE 'P0994' THEN NULL; END;
 END LOOP;
 IF (SELECT count(*) FROM public."HomeGuestPass" WHERE home_id=h)<>before_passes
  OR (SELECT count(*) FROM public."HomeScopedGrant" WHERE home_id=h)<>before_grants THEN RAISE EXCEPTION 'Audit failure left a live share'; END IF;
END $$;
DROP TRIGGER sharing_audit_failure ON public."HomeAuditLog";
DO $$ DECLARE r jsonb; BEGIN
 r:=public.mutate_home_external_share('ddf00000-0000-4000-8000-000000000100','ddf00000-0000-4000-8000-000000000001','guest','create',NULL,
  jsonb_build_object('label','View rollback','included_sections',jsonb_build_array('parking'),'token_hash',repeat('9',64),'max_views',1));
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'View rollback fixture failed'; END IF;
 r:=public.mutate_home_external_share('ddf00000-0000-4000-8000-000000000100','ddf00000-0000-4000-8000-000000000001','scoped','create',NULL,
  jsonb_build_object('resource_type','HomeDocument','resource_id','ddf00000-0000-4000-8000-000000000601','token_hash',repeat('6',64),'max_views',1));
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Receipt rollback fixture failed'; END IF;
END $$;
CREATE TRIGGER sharing_view_failure BEFORE INSERT ON public."HomeGuestPassView"
 FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_external_share();
CREATE TRIGGER sharing_receipt_failure BEFORE INSERT ON public."HomeShareReadReceipt"
 FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_external_share();
DO $$ BEGIN
 BEGIN
  PERFORM public.read_home_external_share('guest',repeat('9',64),NULL,NULL,repeat('7',64));
  RAISE EXCEPTION 'Missing guest view failure';
 EXCEPTION WHEN SQLSTATE 'P0994' THEN NULL; END;
 BEGIN
  PERFORM public.read_home_external_share('scoped',repeat('6',64),NULL,NULL,repeat('7',64));
  RAISE EXCEPTION 'Missing receipt failure';
 EXCEPTION WHEN SQLSTATE 'P0994' THEN NULL; END;
 IF EXISTS(SELECT FROM public."HomeGuestPass" WHERE token_hash=repeat('9',64) AND view_count<>0)
  OR EXISTS(SELECT FROM public."HomeScopedGrant" WHERE token_hash=repeat('6',64) AND view_count<>0)
  OR EXISTS(SELECT FROM public."HomeShareReadReceipt" WHERE receipt_hash=repeat('7',64)) THEN RAISE EXCEPTION 'Downstream failure consumed a view/receipt'; END IF;
END $$;
DROP TRIGGER sharing_view_failure ON public."HomeGuestPassView";
DROP TRIGGER sharing_receipt_failure ON public."HomeShareReadReceipt";

SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','ddf00000-0000-4000-8000-000000000003',true);
DO $$ BEGIN
 IF public.home_has_scoped_grant('ddf00000-0000-4000-8000-000000000100','HomeTask','ddf00000-0000-4000-8000-000000000501','view')
  OR EXISTS(SELECT FROM public."HomeTask" WHERE id='ddf00000-0000-4000-8000-000000000501') THEN
  RAISE EXCEPTION 'Named token grant exposed raw task rows through legacy RLS'; END IF;
END $$;
RESET ROLE;
DO $$ DECLARE t text; op text; BEGIN
 FOREACH t IN ARRAY ARRAY['HomeGuestPass','HomeGuestPassView','HomeScopedGrant','HomeShareReadReceipt'] LOOP
  FOREACH op IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
   IF has_table_privilege('authenticated',format('public.%I',t),op) OR has_table_privilege('anon',format('public.%I',t),op) THEN
    RAISE EXCEPTION 'Client retains % on %',op,t; END IF;
  END LOOP;
 END LOOP;
 IF has_function_privilege('authenticated','public.read_home_external_share(text,text,uuid,text,text)','EXECUTE')
  OR has_function_privilege('anon','public.authorize_home_share_document(text,uuid,uuid,boolean)','EXECUTE') THEN RAISE EXCEPTION 'Public can impersonate share recipient'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(r) ORDER BY role_base,permission) FROM public."HomeRolePermission" r)
  IS DISTINCT FROM (SELECT rows FROM sharing_roles_before) THEN RAISE EXCEPTION 'Sharing changed ordinary role defaults'; END IF;
END $$;
SELECT 'PASS: exact external DTOs, issuer/recipient ceilings, private setup denial, bounded receipts, revocation and direct ACL/RLS closure' AS result;

$contract$, 'home-external-sharing.sql');
SELECT * FROM finish();
ROLLBACK;
